//! The designer's icon set as CPU two-tint masks (build-order B3, icon half), behind the [`Resources`] port: tool icons
//! on a 20 grid (stroke 1.5, one 3 x 3 hot point with corner 0.6) and panel icons on a 16 grid (stroke 1.25), stroke
//! only, round caps and joins (design-system.json `icon`). The path data is [`crate::icon_data`], generated by
//! tools/gen_icons.py from design/icons.json. The icons are original to this kit (design-system.json
//! `icon.provenance`). No SVG library: the path subset the set uses is parsed here.
use crate::display::{IconId, ImageId};
use crate::icon_data;
use crate::paint::{IconMask, ImageRef, Resources};

/// First id of the tool icons (in [`icon_data::TOOL`] order) and of the panel icons ([`icon_data::UI`] order).
pub const TOOL_BASE: u32 = 1000;
pub const UI_BASE: u32 = 2000;
/// The 4 px variant marker of a tool slot: a filled right triangle in the bottom right corner.
pub const VARIANT_MARKER: IconId = IconId(3000);
/// Largest mask side rasterised (scale 8 at 64 logical px).
pub const MAX_ICON_PX: u32 = 512;
/// Masks the cache keeps; reaching it resets the cache whole.
pub const CACHE_CAP: usize = 512;
/// Most flattened segments one icon may produce.
pub const MAX_SEGMENTS: usize = 8192;

/// The id of tool icon `name`.
pub fn tool(name: &str) -> Option<IconId> {
    icon_data::TOOL.iter().position(|t| t.0 == name).map(|i| IconId(TOOL_BASE + i as u32))
}
/// The id of panel icon `name`.
pub fn ui(name: &str) -> Option<IconId> {
    icon_data::UI.iter().position(|t| t.0 == name).map(|i| IconId(UI_BASE + i as u32))
}
/// Every icon id of the set, tool icons first, then panel icons, then the marker.
pub fn all() -> Vec<IconId> {
    let mut v: Vec<IconId> = (0..icon_data::TOOL.len()).map(|i| IconId(TOOL_BASE + i as u32)).collect();
    v.extend((0..icon_data::UI.len()).map(|i| IconId(UI_BASE + i as u32)));
    v.push(VARIANT_MARKER);
    v
}
/// The name of an icon id of this set.
pub fn name(icon: IconId) -> Option<&'static str> {
    let i = icon.0;
    if icon == VARIANT_MARKER {
        return Some("variant_marker");
    }
    if (TOOL_BASE..UI_BASE).contains(&i) {
        return icon_data::TOOL.get((i - TOOL_BASE) as usize).map(|t| t.0);
    }
    if i >= UI_BASE {
        return icon_data::UI.get((i - UI_BASE) as usize).map(|t| t.0);
    }
    None
}

/// Why a path string was refused (typed, never a panic).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum PathError {
    /// A byte that is no command, number or separator, at this byte offset.
    BadCommand(usize),
    /// A number expected at this byte offset.
    BadNumber(usize),
    /// A drawing command before the first moveto.
    MissingMoveTo,
    /// Over [`MAX_SEGMENTS`].
    TooManySegments,
}

/// A flattened subpath: points in grid units; `closed` when it ended with Z.
#[derive(Clone, Debug, PartialEq)]
pub struct Polyline {
    pub points: Vec<(f32, f32)>,
    pub closed: bool,
}

/// Parses the SVG path subset the set uses (M L H V C S A Z, absolute and relative, implicit repeats) and flattens
/// curves and arcs into polylines.
pub fn parse_path(d: &str) -> Result<Vec<Polyline>, PathError> {
    let _ = d;
    Err(PathError::BadCommand(0))
}

/// The mask of `icon` at `px` physical px square: R the stroked form, G the hot point (tool icons only).
pub fn rasterize(icon: IconId, px: u32) -> Option<IconMask> {
    let _ = (icon, px);
    None
}

/// Counters of the icon cache.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct IconStats {
    pub hits: u64,
    pub misses: u64,
    pub resets: u64,
    /// Requests for an id outside the set.
    pub unknown: u64,
}

/// The designer's icons as a [`Resources`] source, masks cached by (icon, px) under [`CACHE_CAP`]. No images.
#[derive(Default)]
pub struct IconSet {
    cache: std::collections::HashMap<(IconId, u32), IconMask>,
    stats: IconStats,
}
impl IconSet {
    pub fn stats(&self) -> IconStats {
        self.stats
    }
    pub fn cached(&self) -> usize {
        self.cache.len()
    }
}
impl Resources for IconSet {
    fn icon(&mut self, icon: IconId, px: u32) -> Option<IconMask> {
        let _ = (icon, px);
        None
    }
    fn image(&self, _: ImageId) -> Option<ImageRef<'_>> {
        None
    }
}
